//! [`PgDdl`]: PostgreSQL DDL generation for the core [`DdlGenerator`] model.
//!
//! Conventions of the model as produced by this driver:
//! * identity columns: `auto_increment = true` and `default =
//!   Some("GENERATED {ALWAYS|BY DEFAULT} AS IDENTITY [(options)]")`; a column
//!   with `auto_increment` and no default becomes `GENERATED BY DEFAULT AS IDENTITY`;
//! * serial columns: `auto_increment = true` with a `nextval(...)` default are
//!   written as `serial` / `bigserial` / `smallserial`;
//! * table options: `tablespace`, `with` (storage parameters), `inherits`,
//!   `using` (table access method), `partition_of` + `partition_bound` (the
//!   table is a partition), `server` + `foreign_options` (foreign tables);
//! * partitions listed in `TableDef::partitions` are created in the parent's schema;
//! * index and trigger definitions reported by the server (`definition`) are
//!   used verbatim, with the `ON <table>` target rewritten to the table being
//!   generated (so DDL can be replayed into another schema).

use crate::dialect::{qualified, quote_ident, string_literal};
use crate::sqltext::{Tok, replace_on_target, strip_on_only, strip_semicolon, tokenize};
use dbiji_core::ddl::*;
use dbiji_core::meta::ObjectKind;
use dbiji_core::{DataKind, DbKind};

/// PostgreSQL DDL generator.
#[derive(Debug, Clone, Default)]
pub struct PgDdl;

fn tname(t: &TableDef) -> String {
    qualified(t.schema.as_deref(), &t.name)
}

fn ident_list(cols: &[String]) -> String {
    cols.iter().map(|c| quote_ident(c)).collect::<Vec<_>>().join(", ")
}

/// Quote a collation name. A locale name is one identifier, dots included
/// (`en_US.utf8`, `C.UTF-8`); a schema qualified one comes quoted (`"public"."mycoll"`)
/// or typed as `myschema.mycoll`.
fn collation_sql(c: &str) -> String {
    if c.contains('"') {
        return c.to_string();
    }
    let quote = |s: &str| format!("\"{}\"", s);
    match c.split_once('.') {
        Some((schema, name)) if !is_locale_name(schema, name) => format!("{}.{}", quote(schema), quote(name)),
        _ => quote(c),
    }
}

/// `en_US.utf8`, `de_DE.ISO-8859-1`, `C.UTF-8`, `POSIX.utf8`: a locale and an encoding.
fn is_locale_name(prefix: &str, suffix: &str) -> bool {
    let encoding = suffix.to_ascii_lowercase().replace(['-', '_'], "");
    let encodings = ["utf8", "iso8859", "latin", "euc", "koi8", "cp125", "windows125", "gb", "big5", "sjis", "ascii", "ansi"];
    let locale = prefix == "C"
        || prefix == "POSIX"
        || prefix.split_once('_').is_some_and(|(lang, country)| {
            (2..=3).contains(&lang.len())
                && lang.chars().all(|c| c.is_ascii_lowercase())
                && !country.is_empty()
                && country.chars().all(|c| c.is_ascii_uppercase() || c.is_ascii_digit())
        });
    locale || encodings.iter().any(|e| encoding.starts_with(e))
}

/// `serial` type for an integer column with a `nextval` default.
fn serial_type(c: &ColumnDef) -> Option<&'static str> {
    let d = c.default.as_deref()?;
    if !c.auto_increment || !d.trim_start().starts_with("nextval(") {
        return None;
    }
    match c.data_type.trim().to_ascii_lowercase().as_str() {
        "integer" | "int" | "int4" | "serial" | "serial4" => Some("serial"),
        "bigint" | "int8" | "bigserial" | "serial8" => Some("bigserial"),
        "smallint" | "int2" | "smallserial" | "serial2" => Some("smallserial"),
        _ => None,
    }
}

/// Identity clause of a column, if it is an identity column.
fn identity_clause(c: &ColumnDef) -> Option<String> {
    if !c.auto_increment || c.generated.is_some() {
        return None;
    }
    match c.default.as_deref().map(str::trim) {
        Some(d) if d.to_ascii_uppercase().starts_with("GENERATED ") => Some(d.to_string()),
        None | Some("") => Some("GENERATED BY DEFAULT AS IDENTITY".to_string()),
        _ => None,
    }
}

/// `name type ...` column definition.
pub(crate) fn column_definition(c: &ColumnDef) -> String {
    let serial = serial_type(c);
    let mut s = format!("{} {}", quote_ident(&c.name), serial.unwrap_or(c.data_type.as_str()));
    if let Some(coll) = c.collation.as_deref().filter(|x| !x.is_empty() && *x != "default") {
        s.push_str(" COLLATE ");
        s.push_str(&collation_sql(coll));
    }
    if let Some(g) = &c.generated {
        match g.strip_suffix(" VIRTUAL") {
            Some(expr) => s.push_str(&format!(" GENERATED ALWAYS AS ({expr}) VIRTUAL")),
            None => s.push_str(&format!(" GENERATED ALWAYS AS ({g}) STORED")),
        }
    } else if let Some(id) = identity_clause(c) {
        s.push(' ');
        s.push_str(&id);
    } else if serial.is_none()
        && let Some(d) = c.default.as_deref().filter(|d| !d.trim().is_empty())
    {
        s.push_str(" DEFAULT ");
        s.push_str(d);
    }
    if !c.nullable {
        s.push_str(" NOT NULL");
    }
    s
}

fn key_clause(kind: &str, k: &KeyDef) -> String {
    match &k.name {
        Some(n) => format!("CONSTRAINT {} {kind} ({})", quote_ident(n), ident_list(&k.columns)),
        None => format!("{kind} ({})", ident_list(&k.columns)),
    }
}

fn check_clause(c: &CheckDef) -> String {
    let expr = c.expression.trim();
    let wrapped = if is_wrapped(expr) { expr.to_string() } else { format!("({expr})") };
    match &c.name {
        Some(n) => format!("CONSTRAINT {} CHECK {wrapped}", quote_ident(n)),
        None => format!("CHECK {wrapped}"),
    }
}

/// The expression is entirely enclosed in one pair of parentheses.
fn is_wrapped(expr: &str) -> bool {
    let toks = tokenize(expr);
    if toks.first().map(|t| t.tok) != Some(Tok::Open) || toks.last().map(|t| t.tok) != Some(Tok::Close) {
        return false;
    }
    let mut depth = 0i32;
    for (i, t) in toks.iter().enumerate() {
        match t.tok {
            Tok::Open => depth += 1,
            Tok::Close => {
                depth -= 1;
                if depth == 0 && i + 1 != toks.len() {
                    return false;
                }
            }
            _ => {}
        }
    }
    true
}

fn fk_clause(fk: &ForeignKeyDef) -> String {
    let mut s = String::new();
    if let Some(n) = &fk.name {
        s.push_str(&format!("CONSTRAINT {} ", quote_ident(n)));
    }
    s.push_str(&format!("FOREIGN KEY ({}) REFERENCES {} ({})", ident_list(&fk.columns), qualified(fk.ref_schema.as_deref(), &fk.ref_table), ident_list(&fk.ref_columns)));
    if fk.on_update != FkAction::NoAction {
        s.push_str(&format!(" ON UPDATE {}", fk.on_update.sql()));
    }
    if fk.on_delete != FkAction::NoAction {
        s.push_str(&format!(" ON DELETE {}", fk.on_delete.sql()));
    }
    if fk.deferrable {
        s.push_str(" DEFERRABLE");
    }
    s
}

fn comment_sql(what: &str, target: &str, comment: Option<&str>) -> String {
    match comment {
        Some(c) => format!("COMMENT ON {what} {target} IS {}", string_literal(c)),
        None => format!("COMMENT ON {what} {target} IS NULL"),
    }
}

/// Indexes that are not created by PRIMARY KEY / UNIQUE constraints.
fn secondary_indexes(t: &TableDef) -> Vec<&IndexDef> {
    t.indexes
        .iter()
        .filter(|i| {
            if i.primary {
                return false;
            }
            if t.primary_key.as_ref().and_then(|k| k.name.as_deref()) == Some(i.name.as_str()) {
                return false;
            }
            if i.unique {
                let cols: Vec<&str> = i.columns.iter().map(|c| c.name.as_str()).collect();
                let backs = t.unique_keys.iter().any(|u| match &u.name {
                    Some(n) => n == &i.name,
                    None => u.columns.iter().map(String::as_str).collect::<Vec<_>>() == cols,
                });
                if backs {
                    return false;
                }
            }
            true
        })
        .collect()
}

fn same_index(a: &IndexDef, b: &IndexDef) -> bool {
    a.name == b.name
        && a.columns == b.columns
        && a.unique == b.unique
        && a.predicate == b.predicate
        && a.include == b.include
        && a.method.as_deref().unwrap_or("btree") == b.method.as_deref().unwrap_or("btree")
}

fn table_kind_word(t: &TableDef) -> &'static str {
    if t.table_kind == TableKind::ForeignTable { "FOREIGN TABLE" } else { "TABLE" }
}

/// Trailing storage clauses: `USING`, `WITH (...)`, `TABLESPACE`.
fn storage_clauses(t: &TableDef) -> String {
    let mut s = String::new();
    if let Some(am) = t.options.get("using").filter(|a| !a.is_empty() && a.as_str() != "heap") {
        s.push_str(&format!(" USING {}", quote_ident(am)));
    }
    if let Some(w) = t.options.get("with").filter(|w| !w.trim().is_empty()) {
        s.push_str(&format!(" WITH ({w})"));
    }
    if let Some(ts) = t.options.get("tablespace").filter(|w| !w.trim().is_empty()) {
        s.push_str(&format!(" TABLESPACE {}", quote_ident(ts)));
    }
    s
}

impl PgDdl {
    /// New generator.
    pub fn new() -> Self {
        PgDdl
    }

    /// Statements changing a user defined type: enum labels added with
    /// `ALTER TYPE ... ADD VALUE` (removed labels cannot be dropped in
    /// PostgreSQL and are reported in a comment), composite attributes added
    /// or dropped, comment changes.
    pub fn alter_type(&self, from: &TypeDef, to: &TypeDef) -> Vec<String> {
        let name = qualified(to.schema.as_deref(), &to.name);
        let mut out = Vec::new();
        if from.name != to.name {
            out.push(format!(
                "ALTER {} {} RENAME TO {}",
                if from.category == "domain" { "DOMAIN" } else { "TYPE" },
                qualified(from.schema.as_deref(), &from.name),
                quote_ident(&to.name)
            ));
        }
        match to.category.as_str() {
            "enum" => {
                for (i, label) in to.elements.iter().enumerate() {
                    if from.elements.contains(label) {
                        continue;
                    }
                    // position relative to the next existing label keeps the order
                    let next_existing = to.elements[i + 1..].iter().find(|l| from.elements.contains(l));
                    let prev_existing = to.elements[..i].iter().rev().find(|l| from.elements.contains(l));
                    let pos = match (prev_existing, next_existing) {
                        (Some(p), _) => format!(" AFTER {}", string_literal(p)),
                        (None, Some(n)) => format!(" BEFORE {}", string_literal(n)),
                        (None, None) => String::new(),
                    };
                    out.push(format!("ALTER TYPE {name} ADD VALUE IF NOT EXISTS {}{pos}", string_literal(label)));
                }
                for label in &from.elements {
                    if !to.elements.contains(label) {
                        out.push(format!("-- enum label {} of {name} cannot be removed without recreating the type", string_literal(label)));
                    }
                }
            }
            "composite" => {
                let attr_name = |e: &str| e.split_whitespace().next().unwrap_or("").to_string();
                let from_names: Vec<String> = from.elements.iter().map(|e| attr_name(e)).collect();
                let to_names: Vec<String> = to.elements.iter().map(|e| attr_name(e)).collect();
                for (e, n) in from.elements.iter().zip(&from_names) {
                    if !to_names.contains(n) {
                        out.push(format!("ALTER TYPE {name} DROP ATTRIBUTE {n}"));
                    } else if let Some(te) = to.elements.iter().find(|x| attr_name(x) == *n)
                        && te != e
                    {
                        let ty = te.split_once(char::is_whitespace).map(|(_, t)| t.trim()).unwrap_or("");
                        out.push(format!("ALTER TYPE {name} ALTER ATTRIBUTE {n} TYPE {ty}"));
                    }
                }
                for (e, n) in to.elements.iter().zip(&to_names) {
                    if !from_names.contains(n) {
                        out.push(format!("ALTER TYPE {name} ADD ATTRIBUTE {e}"));
                    }
                }
            }
            _ => {
                if from.definition != to.definition && !to.definition.is_empty() {
                    let what = if to.category == "domain" { "DOMAIN" } else { "TYPE" };
                    out.push(format!("DROP {what} {name}"));
                    out.push(strip_semicolon(&to.definition).to_string());
                }
            }
        }
        if from.comment != to.comment {
            let what = if to.category == "domain" { "DOMAIN" } else { "TYPE" };
            out.push(comment_sql(what, &name, to.comment.as_deref()));
        }
        out
    }

    fn create_partition_table(&self, t: &TableDef, parent: &str, include_fks: bool) -> String {
        let head = match t.table_kind {
            TableKind::Temporary => "CREATE TEMPORARY TABLE",
            TableKind::Unlogged => "CREATE UNLOGGED TABLE",
            TableKind::ForeignTable => "CREATE FOREIGN TABLE",
            _ => "CREATE TABLE",
        };
        let mut s = format!("{head} {} PARTITION OF {parent}", tname(t));
        let mut body = Vec::new();
        if let Some(pk) = t.primary_key.as_ref().filter(|k| !k.columns.is_empty()) {
            body.push(key_clause("PRIMARY KEY", pk));
        }
        for u in &t.unique_keys {
            body.push(key_clause("UNIQUE", u));
        }
        for c in &t.checks {
            body.push(check_clause(c));
        }
        if include_fks {
            for fk in &t.foreign_keys {
                body.push(fk_clause(fk));
            }
        }
        if !body.is_empty() {
            s.push_str(&format!(" (\n    {}\n)", body.join(",\n    ")));
        }
        let bound = t.options.get("partition_bound").map(String::as_str).unwrap_or("DEFAULT");
        s.push(' ');
        s.push_str(bound);
        if let Some(p) = &t.partitioning {
            s.push_str(&format!(" PARTITION BY {} ({})", p.strategy, p.key));
        }
        if t.table_kind == TableKind::ForeignTable
            && let Some(server) = t.options.get("server")
        {
            s.push_str(&format!(" SERVER {}", quote_ident(server)));
            if let Some(o) = t.options.get("foreign_options").filter(|o| !o.is_empty()) {
                s.push_str(&format!(" OPTIONS ({o})"));
            }
        }
        s.push_str(&storage_clauses(t));
        s
    }
}

impl DdlGenerator for PgDdl {
    fn create_table(&self, t: &TableDef, include_foreign_keys: bool) -> Vec<String> {
        let name = tname(t);
        let mut out = Vec::new();
        if let Some(parent) = t.options.get("partition_of").filter(|p| !p.is_empty()) {
            out.push(self.create_partition_table(t, parent, include_foreign_keys));
        } else {
            let head = match t.table_kind {
                TableKind::Temporary => "CREATE TEMPORARY TABLE",
                TableKind::Unlogged => "CREATE UNLOGGED TABLE",
                TableKind::ForeignTable => "CREATE FOREIGN TABLE",
                _ => "CREATE TABLE",
            };
            let mut body: Vec<String> = t.columns.iter().map(column_definition).collect();
            if let Some(pk) = t.primary_key.as_ref().filter(|k| !k.columns.is_empty()) {
                body.push(key_clause("PRIMARY KEY", pk));
            }
            for u in &t.unique_keys {
                body.push(key_clause("UNIQUE", u));
            }
            for c in &t.checks {
                body.push(check_clause(c));
            }
            if include_foreign_keys {
                for fk in &t.foreign_keys {
                    body.push(fk_clause(fk));
                }
            }
            let mut s = if body.is_empty() { format!("{head} {name} ()") } else { format!("{head} {name} (\n    {}\n)", body.join(",\n    ")) };
            if let Some(inh) = t.options.get("inherits").filter(|i| !i.is_empty()) {
                s.push_str(&format!(" INHERITS ({inh})"));
            }
            if let Some(p) = &t.partitioning {
                s.push_str(&format!(" PARTITION BY {} ({})", p.strategy, p.key));
            }
            if t.table_kind == TableKind::ForeignTable
                && let Some(server) = t.options.get("server")
            {
                s.push_str(&format!(" SERVER {}", quote_ident(server)));
                if let Some(o) = t.options.get("foreign_options").filter(|o| !o.is_empty()) {
                    s.push_str(&format!(" OPTIONS ({o})"));
                }
            }
            s.push_str(&storage_clauses(t));
            out.push(s);
        }
        for p in &t.partitions {
            out.push(format!(
                "CREATE TABLE {} PARTITION OF {name} {}",
                qualified(t.schema.as_deref(), &p.name),
                if p.bound.trim().is_empty() { "DEFAULT" } else { p.bound.trim() }
            ));
        }
        if let Some(c) = &t.comment {
            out.push(comment_sql(table_kind_word(t), &name, Some(c)));
        }
        for c in &t.columns {
            if let Some(cm) = &c.comment {
                out.push(comment_sql("COLUMN", &format!("{name}.{}", quote_ident(&c.name)), Some(cm)));
            }
        }
        for idx in secondary_indexes(t) {
            out.push(self.create_index(t, idx));
            if let Some(cm) = &idx.comment {
                out.push(comment_sql("INDEX", &qualified(t.schema.as_deref(), &idx.name), Some(cm)));
            }
        }
        for trig in &t.triggers {
            out.extend(self.create_trigger(t, trig));
        }
        out
    }

    fn drop_table(&self, schema: Option<&str>, name: &str, cascade: bool) -> String {
        format!("DROP TABLE {}{}", qualified(schema, name), if cascade { " CASCADE" } else { "" })
    }

    fn rename_table(&self, schema: Option<&str>, old_name: &str, new_name: &str) -> String {
        format!("ALTER TABLE {} RENAME TO {}", qualified(schema, old_name), quote_ident(new_name))
    }

    fn alter_table(&self, from: &TableDef, to: &TableDef, renamed: &[(String, String)]) -> Vec<String> {
        let mut out = Vec::new();
        if from.name != to.name || from.schema != to.schema {
            if from.name != to.name {
                out.push(self.rename_table(from.schema.as_deref(), &from.name, &to.name));
            }
            if from.schema != to.schema
                && let Some(s) = &to.schema
            {
                out.push(format!("ALTER TABLE {} SET SCHEMA {}", qualified(from.schema.as_deref(), &to.name), quote_ident(s)));
            }
        }
        let t = tname(to);
        let (pairs, dropped, added) = dbiji_core::dialect::ansi::match_columns(from, to, renamed);

        // 1. drop foreign keys that change or disappear (first, they depend on keys)
        for fk in &from.foreign_keys {
            if !to.foreign_keys.contains(fk) {
                out.push(self.drop_foreign_key(to, fk));
            }
        }
        // 2. drop triggers and indexes that change or disappear
        for tr in &from.triggers {
            if !to.triggers.iter().any(|x| x.name == tr.name && x.definition == tr.definition && x.enabled == tr.enabled) {
                if to.triggers.iter().any(|x| x.name == tr.name && x.definition == tr.definition) {
                    continue; // only enabled flag changed, handled below
                }
                out.push(self.drop_trigger(to, tr));
            }
        }
        let from_idx = secondary_indexes(from);
        let to_idx = secondary_indexes(to);
        for i in &from_idx {
            if !to_idx.iter().any(|x| same_index(x, i)) {
                out.push(self.drop_index(to, i));
            }
        }
        // 3. drop constraints that change or disappear
        for c in &from.checks {
            if !to.checks.contains(c) {
                out.push(self.drop_check(to, c));
            }
        }
        for u in &from.unique_keys {
            if !to.unique_keys.contains(u) {
                out.push(self.drop_unique_key(to, u));
            }
        }
        let pk_changed = from.primary_key != to.primary_key;
        if pk_changed && let Some(pk) = from.primary_key.as_ref().filter(|k| !k.columns.is_empty()) {
            out.push(self.drop_primary_key(to, pk));
        }
        // 4. drop columns
        for c in &dropped {
            out.push(self.drop_column(to, &c.name));
        }
        // 5. rename and alter columns
        for (fc, tc) in &pairs {
            let col = quote_ident(&tc.name);
            if fc.name != tc.name {
                out.push(format!("ALTER TABLE {t} RENAME COLUMN {} TO {col}", quote_ident(&fc.name)));
            }
            let from_identity = identity_clause(fc);
            let to_identity = identity_clause(tc);
            let from_default = if from_identity.is_some() { None } else { fc.default.clone() };
            let to_default = if to_identity.is_some() { None } else { tc.default.clone() };
            // generated expression changes
            if fc.generated != tc.generated {
                match (&fc.generated, &tc.generated) {
                    (Some(_), None) => out.push(format!("ALTER TABLE {t} ALTER COLUMN {col} DROP EXPRESSION")),
                    (_, Some(g)) => out.push(format!("ALTER TABLE {t} ALTER COLUMN {col} SET EXPRESSION AS ({})", g.strip_suffix(" VIRTUAL").unwrap_or(g))),
                    (None, None) => {}
                }
            }
            // identity removed first (frees the column for type / default changes)
            if from_identity.is_some() && to_identity.is_none() {
                out.push(format!("ALTER TABLE {t} ALTER COLUMN {col} DROP IDENTITY IF EXISTS"));
            }
            let type_changed = fc.data_type != tc.data_type || fc.collation != tc.collation;
            if from_default != to_default && from_default.is_some() && tc.generated.is_none() {
                // drop the old default before changing the type (it may not cast)
                if type_changed || to_default.is_none() {
                    out.push(format!("ALTER TABLE {t} ALTER COLUMN {col} DROP DEFAULT"));
                }
            }
            if type_changed {
                let mut s = format!("ALTER TABLE {t} ALTER COLUMN {col} TYPE {}", tc.data_type);
                if let Some(coll) = tc.collation.as_deref().filter(|c| !c.is_empty() && *c != "default") {
                    s.push_str(&format!(" COLLATE {}", collation_sql(coll)));
                }
                if fc.data_type != tc.data_type {
                    s.push_str(&format!(" USING {col}::{}", tc.data_type));
                }
                out.push(s);
            }
            if from_default != to_default
                && tc.generated.is_none()
                && let Some(d) = to_default.as_deref().filter(|d| !d.trim().is_empty())
            {
                out.push(format!("ALTER TABLE {t} ALTER COLUMN {col} SET DEFAULT {d}"));
            }
            if fc.nullable != tc.nullable {
                out.push(format!("ALTER TABLE {t} ALTER COLUMN {col} {} NOT NULL", if tc.nullable { "DROP" } else { "SET" }));
            }
            match (&from_identity, &to_identity) {
                (None, Some(id)) => {
                    if tc.nullable {
                        out.push(format!("ALTER TABLE {t} ALTER COLUMN {col} SET NOT NULL"));
                    }
                    out.push(format!("ALTER TABLE {t} ALTER COLUMN {col} ADD {id}"));
                }
                (Some(a), Some(b)) if a != b => {
                    let up = b.to_ascii_uppercase();
                    let kind = if up.contains("ALWAYS") { "ALWAYS" } else { "BY DEFAULT" };
                    out.push(format!("ALTER TABLE {t} ALTER COLUMN {col} SET GENERATED {kind}"));
                }
                _ => {}
            }
            if fc.comment != tc.comment {
                out.push(comment_sql("COLUMN", &format!("{t}.{col}"), tc.comment.as_deref()));
            }
        }
        // 6. add columns
        for c in &added {
            out.extend(self.add_column(to, c));
        }
        // 7. add keys, checks, indexes, triggers
        if pk_changed && let Some(pk) = to.primary_key.as_ref().filter(|k| !k.columns.is_empty()) {
            out.push(self.add_primary_key(to, pk));
        }
        for u in &to.unique_keys {
            if !from.unique_keys.contains(u) {
                out.push(self.add_unique_key(to, u));
            }
        }
        for c in &to.checks {
            if !from.checks.contains(c) {
                out.push(self.add_check(to, c));
            }
        }
        for i in &to_idx {
            if !from_idx.iter().any(|x| same_index(x, i)) {
                out.push(self.create_index(to, i));
            }
            let old_comment = from_idx.iter().find(|x| x.name == i.name).and_then(|x| x.comment.clone());
            if old_comment != i.comment {
                out.push(comment_sql("INDEX", &qualified(to.schema.as_deref(), &i.name), i.comment.as_deref()));
            }
        }
        for tr in &to.triggers {
            match from.triggers.iter().find(|x| x.name == tr.name) {
                Some(old) if old.definition == tr.definition => {
                    if old.enabled != tr.enabled {
                        out.push(format!("ALTER TABLE {t} {} TRIGGER {}", if tr.enabled { "ENABLE" } else { "DISABLE" }, quote_ident(&tr.name)));
                    }
                    if old.comment != tr.comment {
                        out.push(comment_sql("TRIGGER", &format!("{} ON {t}", quote_ident(&tr.name)), tr.comment.as_deref()));
                    }
                }
                _ => out.extend(self.create_trigger(to, tr)),
            }
        }
        // 8. options
        let opt = |d: &TableDef, k: &str| d.options.get(k).cloned().unwrap_or_default();
        if opt(from, "tablespace") != opt(to, "tablespace") {
            let ts = opt(to, "tablespace");
            out.push(format!("ALTER TABLE {t} SET TABLESPACE {}", if ts.is_empty() { "pg_default".to_string() } else { quote_ident(&ts) }));
        }
        if opt(from, "with") != opt(to, "with") {
            let old: Vec<String> = opt(from, "with").split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
            let new: Vec<String> = opt(to, "with").split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
            let new_keys: Vec<&str> = new.iter().map(|s| s.split('=').next().unwrap_or("").trim()).collect();
            let reset: Vec<&str> = old.iter().map(|s| s.split('=').next().unwrap_or("").trim()).filter(|k| !new_keys.contains(k)).collect();
            if !reset.is_empty() {
                out.push(format!("ALTER TABLE {t} RESET ({})", reset.join(", ")));
            }
            if !new.is_empty() {
                out.push(format!("ALTER TABLE {t} SET ({})", new.join(", ")));
            }
        }
        if from.table_kind != to.table_kind {
            match (from.table_kind, to.table_kind) {
                (TableKind::Unlogged, TableKind::Table) => out.push(format!("ALTER TABLE {t} SET LOGGED")),
                (TableKind::Table, TableKind::Unlogged) => out.push(format!("ALTER TABLE {t} SET UNLOGGED")),
                _ => {}
            }
        }
        if from.comment != to.comment {
            out.push(comment_sql(table_kind_word(to), &t, to.comment.as_deref()));
        }
        // 9. foreign keys last
        for fk in &to.foreign_keys {
            if !from.foreign_keys.contains(fk) {
                out.push(self.add_foreign_key(to, fk));
            }
        }
        out
    }

    fn add_column(&self, table: &TableDef, column: &ColumnDef) -> Vec<String> {
        let t = tname(table);
        let mut out = vec![format!("ALTER TABLE {t} ADD COLUMN {}", column_definition(column))];
        if let Some(c) = &column.comment {
            out.push(comment_sql("COLUMN", &format!("{t}.{}", quote_ident(&column.name)), Some(c)));
        }
        out
    }

    fn drop_column(&self, table: &TableDef, column: &str) -> String {
        format!("ALTER TABLE {} DROP COLUMN {}", tname(table), quote_ident(column))
    }

    fn create_index(&self, table: &TableDef, index: &IndexDef) -> String {
        if let Some(def) = index.definition.as_deref().map(str::trim).filter(|d| !d.is_empty()) {
            let def = strip_semicolon(def);
            // use the server definition when it still names this index
            let toks = tokenize(def);
            let names_index = toks.iter().any(|t| match t.tok {
                Tok::Word(w) => w == index.name,
                Tok::Quoted(q) => q.trim_matches('"').replace("\"\"", "\"") == index.name,
                _ => false,
            });
            if names_index {
                // pg_get_indexdef reports partitioned indexes as `ON ONLY parent`;
                // without ONLY the index is created on all partitions as well
                let def = if table.table_kind == TableKind::PartitionedTable { strip_on_only(def) } else { def.to_string() };
                return replace_on_target(&def, &tname(table)).unwrap_or(def);
            }
        }
        let mut s = format!("CREATE {}INDEX {} ON {}", if index.unique { "UNIQUE " } else { "" }, quote_ident(&index.name), tname(table));
        if let Some(m) = index.method.as_deref().filter(|m| !m.is_empty() && !m.eq_ignore_ascii_case("btree")) {
            s.push_str(&format!(" USING {}", quote_ident(&m.to_ascii_lowercase())));
        }
        let cols: Vec<String> = index
            .columns
            .iter()
            .map(|c| {
                let mut x = if c.is_expression { if is_wrapped(&c.name) { c.name.clone() } else { format!("({})", c.name) } } else { quote_ident(&c.name) };
                if c.descending {
                    x.push_str(" DESC");
                }
                x
            })
            .collect();
        s.push_str(&format!(" ({})", cols.join(", ")));
        if !index.include.is_empty() {
            s.push_str(&format!(" INCLUDE ({})", ident_list(&index.include)));
        }
        if let Some(p) = index.predicate.as_deref().filter(|p| !p.trim().is_empty()) {
            s.push_str(" WHERE ");
            s.push_str(p);
        }
        s
    }

    fn drop_index(&self, table: &TableDef, index: &IndexDef) -> String {
        format!("DROP INDEX {}", qualified(table.schema.as_deref(), &index.name))
    }

    fn add_primary_key(&self, table: &TableDef, key: &KeyDef) -> String {
        format!("ALTER TABLE {} ADD {}", tname(table), key_clause("PRIMARY KEY", key))
    }

    fn drop_primary_key(&self, table: &TableDef, key: &KeyDef) -> String {
        let name = key.name.clone().unwrap_or_else(|| format!("{}_pkey", table.name));
        format!("ALTER TABLE {} DROP CONSTRAINT {}", tname(table), quote_ident(&name))
    }

    fn add_unique_key(&self, table: &TableDef, key: &KeyDef) -> String {
        format!("ALTER TABLE {} ADD {}", tname(table), key_clause("UNIQUE", key))
    }

    fn drop_unique_key(&self, table: &TableDef, key: &KeyDef) -> String {
        let name = key.name.clone().unwrap_or_else(|| format!("{}_{}_key", table.name, key.columns.join("_")));
        format!("ALTER TABLE {} DROP CONSTRAINT {}", tname(table), quote_ident(&name))
    }

    fn add_check(&self, table: &TableDef, check: &CheckDef) -> String {
        format!("ALTER TABLE {} ADD {}", tname(table), check_clause(check))
    }

    fn drop_check(&self, table: &TableDef, check: &CheckDef) -> String {
        let name = check.name.clone().unwrap_or_else(|| format!("{}_check", table.name));
        format!("ALTER TABLE {} DROP CONSTRAINT {}", tname(table), quote_ident(&name))
    }

    fn add_foreign_key(&self, table: &TableDef, fk: &ForeignKeyDef) -> String {
        format!("ALTER TABLE {} ADD {}", tname(table), fk_clause(fk))
    }

    fn drop_foreign_key(&self, table: &TableDef, fk: &ForeignKeyDef) -> String {
        let name = fk.name.clone().unwrap_or_else(|| format!("{}_{}_fkey", table.name, fk.columns.join("_")));
        format!("ALTER TABLE {} DROP CONSTRAINT {}", tname(table), quote_ident(&name))
    }

    fn create_trigger(&self, table: &TableDef, trigger: &TriggerDef) -> Vec<String> {
        let t = tname(table);
        let def = if trigger.definition.trim().is_empty() {
            let timing = if trigger.timing.is_empty() { "BEFORE" } else { trigger.timing.as_str() };
            let events = if trigger.events.is_empty() { "INSERT".to_string() } else { trigger.events.join(" OR ") };
            let body = trigger.body.clone().unwrap_or_else(|| "trigger_function()".into());
            format!(
                "CREATE TRIGGER {} {timing} {events} ON {t} FOR EACH {} EXECUTE FUNCTION {body}",
                quote_ident(&trigger.name),
                if trigger.for_each_row { "ROW" } else { "STATEMENT" }
            )
        } else {
            let d = strip_semicolon(trigger.definition.trim());
            replace_on_target(d, &t).unwrap_or_else(|| d.to_string())
        };
        let mut out = vec![def];
        if !trigger.enabled {
            out.push(format!("ALTER TABLE {t} DISABLE TRIGGER {}", quote_ident(&trigger.name)));
        }
        if let Some(c) = &trigger.comment {
            out.push(comment_sql("TRIGGER", &format!("{} ON {t}", quote_ident(&trigger.name)), Some(c)));
        }
        out
    }

    fn drop_trigger(&self, table: &TableDef, trigger: &TriggerDef) -> String {
        format!("DROP TRIGGER {} ON {}", quote_ident(&trigger.name), tname(table))
    }

    fn create_view(&self, view: &ViewDef, or_replace: bool) -> Vec<String> {
        let name = qualified(view.schema.as_deref(), &view.name);
        let select = strip_semicolon(view.definition.trim());
        let mut out = Vec::new();
        let with_opts: Vec<String> =
            view.options.iter().filter(|(k, _)| !matches!(k.as_str(), "check_option" | "tablespace" | "using" | "populated")).map(|(k, v)| format!("{k}={v}")).collect();
        if view.materialized {
            if or_replace {
                out.push(format!("DROP MATERIALIZED VIEW IF EXISTS {name}"));
            }
            let mut s = format!("CREATE MATERIALIZED VIEW {name}");
            if let Some(am) = view.options.get("using").filter(|a| !a.is_empty() && a.as_str() != "heap") {
                s.push_str(&format!(" USING {}", quote_ident(am)));
            }
            if !with_opts.is_empty() {
                s.push_str(&format!(" WITH ({})", with_opts.join(", ")));
            }
            if let Some(ts) = view.options.get("tablespace").filter(|t| !t.is_empty()) {
                s.push_str(&format!(" TABLESPACE {}", quote_ident(ts)));
            }
            s.push_str(&format!(" AS\n{select}"));
            if view.options.get("populated").map(String::as_str) == Some("false") {
                s.push_str("\nWITH NO DATA");
            }
            out.push(s);
        } else {
            let mut s = format!("CREATE {}VIEW {name}", if or_replace { "OR REPLACE " } else { "" });
            if !with_opts.is_empty() {
                s.push_str(&format!(" WITH ({})", with_opts.join(", ")));
            }
            s.push_str(&format!(" AS\n{select}"));
            if let Some(co) = view.options.get("check_option") {
                s.push_str(&format!("\nWITH {} CHECK OPTION", co.to_ascii_uppercase()));
            }
            out.push(s);
        }
        let what = if view.materialized { "MATERIALIZED VIEW" } else { "VIEW" };
        if let Some(c) = &view.comment {
            out.push(comment_sql(what, &name, Some(c)));
        }
        for c in &view.columns {
            if let Some(cm) = &c.comment {
                out.push(comment_sql("COLUMN", &format!("{name}.{}", quote_ident(&c.name)), Some(cm)));
            }
        }
        out
    }

    fn drop_view(&self, view: &ViewDef) -> String {
        format!("DROP {}VIEW {}", if view.materialized { "MATERIALIZED " } else { "" }, qualified(view.schema.as_deref(), &view.name))
    }

    fn create_sequence(&self, seq: &SequenceDef) -> String {
        let mut s = format!("CREATE SEQUENCE {}", qualified(seq.schema.as_deref(), &seq.name));
        if let Some(t) = seq.data_type.as_deref().filter(|t| !t.is_empty() && *t != "bigint") {
            s.push_str(&format!(" AS {t}"));
        }
        if let Some(v) = seq.increment {
            s.push_str(&format!(" INCREMENT BY {v}"));
        }
        if let Some(v) = seq.min_value {
            s.push_str(&format!(" MINVALUE {v}"));
        }
        if let Some(v) = seq.max_value {
            s.push_str(&format!(" MAXVALUE {v}"));
        }
        if let Some(v) = seq.start {
            s.push_str(&format!(" START WITH {v}"));
        }
        if let Some(v) = seq.cache {
            s.push_str(&format!(" CACHE {v}"));
        }
        s.push_str(if seq.cycle { " CYCLE" } else { " NO CYCLE" });
        s
    }

    fn alter_sequence(&self, from: &SequenceDef, to: &SequenceDef) -> Vec<String> {
        let mut out = Vec::new();
        if from.name != to.name {
            out.push(format!("ALTER SEQUENCE {} RENAME TO {}", qualified(from.schema.as_deref(), &from.name), quote_ident(&to.name)));
        }
        let name = qualified(to.schema.as_deref(), &to.name);
        let mut parts = Vec::new();
        if from.data_type != to.data_type
            && let Some(t) = &to.data_type
        {
            parts.push(format!("AS {t}"));
        }
        if from.increment != to.increment
            && let Some(v) = to.increment
        {
            parts.push(format!("INCREMENT BY {v}"));
        }
        if from.min_value != to.min_value {
            parts.push(to.min_value.map(|v| format!("MINVALUE {v}")).unwrap_or_else(|| "NO MINVALUE".into()));
        }
        if from.max_value != to.max_value {
            parts.push(to.max_value.map(|v| format!("MAXVALUE {v}")).unwrap_or_else(|| "NO MAXVALUE".into()));
        }
        if from.start != to.start
            && let Some(v) = to.start
        {
            parts.push(format!("START WITH {v}"));
        }
        if from.cache != to.cache
            && let Some(v) = to.cache
        {
            parts.push(format!("CACHE {v}"));
        }
        if from.cycle != to.cycle {
            parts.push(if to.cycle { "CYCLE".into() } else { "NO CYCLE".into() });
        }
        if from.owned_by != to.owned_by {
            parts.push(format!("OWNED BY {}", to.owned_by.clone().unwrap_or_else(|| "NONE".into())));
        }
        if !parts.is_empty() {
            out.push(format!("ALTER SEQUENCE {name} {}", parts.join(" ")));
        }
        if from.comment != to.comment {
            out.push(comment_sql("SEQUENCE", &name, to.comment.as_deref()));
        }
        out
    }

    fn drop_sequence(&self, seq: &SequenceDef) -> String {
        format!("DROP SEQUENCE {}", qualified(seq.schema.as_deref(), &seq.name))
    }

    fn create_routine(&self, routine: &RoutineDef) -> Vec<String> {
        let mut out = Vec::new();
        let def = strip_semicolon(routine.definition.trim());
        if !def.is_empty() {
            out.push(def.to_string());
        }
        if let Some(c) = &routine.comment {
            let what = match routine.kind {
                Some(ObjectKind::Procedure) => "PROCEDURE",
                Some(ObjectKind::Aggregate) => "AGGREGATE",
                _ => "FUNCTION",
            };
            out.push(comment_sql(what, &format!("{}({})", qualified(routine.schema.as_deref(), &routine.name), routine.arguments), Some(c)));
        }
        out
    }

    fn drop_routine(&self, routine: &RoutineDef) -> String {
        let what = match routine.kind {
            Some(ObjectKind::Procedure) => "PROCEDURE",
            Some(ObjectKind::Aggregate) => "AGGREGATE",
            _ => "FUNCTION",
        };
        format!("DROP {what} {}({})", qualified(routine.schema.as_deref(), &routine.name), routine.arguments)
    }

    fn create_type(&self, ty: &TypeDef) -> Vec<String> {
        let mut out = Vec::new();
        let def = strip_semicolon(ty.definition.trim());
        if !def.is_empty() {
            out.push(def.to_string());
        }
        if let Some(c) = &ty.comment {
            let what = if ty.category == "domain" { "DOMAIN" } else { "TYPE" };
            out.push(comment_sql(what, &qualified(ty.schema.as_deref(), &ty.name), Some(c)));
        }
        out
    }

    fn drop_type(&self, ty: &TypeDef) -> Option<String> {
        let what = if ty.category == "domain" { "DOMAIN" } else { "TYPE" };
        Some(format!("DROP {what} {}", qualified(ty.schema.as_deref(), &ty.name)))
    }

    fn create_schema(&self, name: &str) -> String {
        format!("CREATE SCHEMA {}", quote_ident(name))
    }

    fn drop_schema(&self, name: &str, cascade: bool) -> String {
        format!("DROP SCHEMA {}{}", quote_ident(name), if cascade { " CASCADE" } else { "" })
    }

    fn map_type(&self, source: DbKind, data_type: &str, kind: DataKind) -> String {
        map_type(source, data_type, kind)
    }

    fn default_type_for(&self, kind: DataKind) -> String {
        default_type_for(kind).to_string()
    }
}

/// Default PostgreSQL type for a logical kind.
pub(crate) fn default_type_for(kind: DataKind) -> &'static str {
    match kind {
        DataKind::Bool => "boolean",
        DataKind::Int => "bigint",
        DataKind::Float => "double precision",
        DataKind::Decimal => "numeric",
        DataKind::Text | DataKind::Enum | DataKind::Other | DataKind::Range => "text",
        DataKind::Binary => "bytea",
        DataKind::Date => "date",
        DataKind::Time => "time",
        DataKind::TimeTz => "timetz",
        DataKind::DateTime => "timestamp",
        DataKind::DateTimeTz => "timestamptz",
        DataKind::Interval => "interval",
        DataKind::Uuid => "uuid",
        DataKind::Json => "jsonb",
        DataKind::Xml => "xml",
        DataKind::Array => "text[]",
        DataKind::Geometry => "geometry",
        DataKind::Network => "inet",
        DataKind::Bit => "varbit",
    }
}

/// Split `name(args) rest` into lower case base name, the argument text and flags.
fn parse_type(t: &str) -> (String, Option<String>, String) {
    let t = t.trim();
    match t.find('(') {
        Some(open) => {
            let close = t.rfind(')').unwrap_or(t.len());
            let base = t[..open].trim().to_ascii_lowercase();
            let args = t.get(open + 1..close).map(|a| a.trim().to_string());
            let rest = t.get(close + 1..).unwrap_or("").trim().to_ascii_lowercase();
            (base, args, rest)
        }
        None => {
            let lower = t.to_ascii_lowercase();
            (lower, None, String::new())
        }
    }
}

fn with_args(base: &str, args: &Option<String>) -> String {
    match args {
        Some(a) if !a.is_empty() => format!("{base}({a})"),
        _ => base.to_string(),
    }
}

/// Convert a column type of another product into PostgreSQL.
pub(crate) fn map_type(source: DbKind, data_type: &str, kind: DataKind) -> String {
    let raw = data_type.trim();
    if raw.is_empty() {
        return default_type_for(kind).to_string();
    }
    let (base, args, rest) = parse_type(raw);
    let unsigned = rest.contains("unsigned") || base.ends_with(" unsigned");
    let base = base.trim_end_matches(" unsigned").trim_end_matches(" zerofill").trim().to_string();
    match source {
        DbKind::Postgres => raw.to_string(),
        DbKind::CockroachDb => match base.as_str() {
            "string" => {
                if args.is_some() {
                    with_args("varchar", &args)
                } else {
                    "text".into()
                }
            }
            "bytes" => "bytea".into(),
            "int" | "integer" | "int8" | "int64" => "bigint".into(),
            "int4" | "int32" => "integer".into(),
            "int2" | "int16" => "smallint".into(),
            "float" | "float8" => "double precision".into(),
            "decimal" => with_args("numeric", &args),
            _ => raw.to_string(),
        },
        DbKind::MySql | DbKind::MariaDb => match base.as_str() {
            "tinyint" if args.as_deref() == Some("1") && !unsigned => "boolean".into(),
            "bool" | "boolean" => "boolean".into(),
            "tinyint" | "smallint" if !unsigned => "smallint".into(),
            "tinyint" => "smallint".into(),
            "smallint" => "integer".into(),
            "mediumint" | "int" | "integer" if !unsigned => "integer".into(),
            "mediumint" => "integer".into(),
            "int" | "integer" => "bigint".into(),
            "bigint" if !unsigned => "bigint".into(),
            "bigint" | "serial" => "numeric(20)".into(),
            "float" => "real".into(),
            "double" | "double precision" | "real" => "double precision".into(),
            "decimal" | "numeric" | "dec" | "fixed" => with_args("numeric", &args),
            "bit" if args.as_deref().is_none_or(|a| a == "1") => "boolean".into(),
            "bit" => with_args("bit", &args),
            "year" => "smallint".into(),
            "date" => "date".into(),
            "datetime" => with_args("timestamp", &args),
            "timestamp" => with_args("timestamptz", &args),
            "time" => with_args("time", &args),
            "char" => with_args("char", &args),
            "varchar" => with_args("varchar", &args),
            "tinytext" | "text" | "mediumtext" | "longtext" | "long" | "long varchar" => "text".into(),
            "binary" | "varbinary" | "tinyblob" | "blob" | "mediumblob" | "longblob" => "bytea".into(),
            "enum" | "set" => "text".into(),
            "json" => "jsonb".into(),
            "uuid" => "uuid".into(),
            "inet4" | "inet6" => "inet".into(),
            "geometry" | "point" | "linestring" | "polygon" | "multipoint" | "multilinestring" | "multipolygon" | "geometrycollection" => "geometry".into(),
            _ => default_type_for(kind).to_string(),
        },
        DbKind::Sqlite => {
            // SQLite type affinity rules
            if base.contains("int") {
                "bigint".into()
            } else if base == "boolean" || base == "bool" {
                "boolean".into()
            } else if base.starts_with("varchar") || base.starts_with("nvarchar") || base.starts_with("character") {
                with_args("varchar", &args)
            } else if base.contains("char") || base.contains("clob") || base.contains("text") {
                "text".into()
            } else if base.contains("blob") || base.is_empty() {
                "bytea".into()
            } else if base.contains("real") || base.contains("floa") || base.contains("doub") {
                "double precision".into()
            } else if base == "datetime" || base == "timestamp" {
                "timestamp".into()
            } else if base == "date" {
                "date".into()
            } else if base == "time" {
                "time".into()
            } else if base.contains("dec") || base.contains("num") {
                with_args("numeric", &args)
            } else if base == "json" {
                "jsonb".into()
            } else if base == "uuid" {
                "uuid".into()
            } else {
                default_type_for(kind).to_string()
            }
        }
        DbKind::SqlServer => match base.as_str() {
            "bit" => "boolean".into(),
            "tinyint" | "smallint" => "smallint".into(),
            "int" => "integer".into(),
            "bigint" => "bigint".into(),
            "decimal" | "numeric" => with_args("numeric", &args),
            "money" => "numeric(19,4)".into(),
            "smallmoney" => "numeric(10,4)".into(),
            "float" => match args.as_deref().and_then(|a| a.parse::<u32>().ok()) {
                Some(n) if n <= 24 => "real".into(),
                _ => "double precision".into(),
            },
            "real" => "real".into(),
            "date" => "date".into(),
            "datetime" => "timestamp(3)".into(),
            "datetime2" => with_args("timestamp", &args.filter(|a| a.parse::<u32>().is_ok_and(|p| p <= 6))),
            "smalldatetime" => "timestamp(0)".into(),
            "datetimeoffset" => with_args("timestamptz", &args.filter(|a| a.parse::<u32>().is_ok_and(|p| p <= 6))),
            "time" => with_args("time", &args.filter(|a| a.parse::<u32>().is_ok_and(|p| p <= 6))),
            "char" | "nchar" => with_args("char", &args),
            "varchar" | "nvarchar" => match args.as_deref() {
                Some(a) if a.eq_ignore_ascii_case("max") => "text".into(),
                _ => with_args("varchar", &args),
            },
            "text" | "ntext" | "sysname" | "sql_variant" | "hierarchyid" => "text".into(),
            "binary" | "varbinary" | "image" | "rowversion" | "timestamp" => "bytea".into(),
            "uniqueidentifier" => "uuid".into(),
            "xml" => "xml".into(),
            "geography" => "geography".into(),
            "geometry" => "geometry".into(),
            _ => default_type_for(kind).to_string(),
        },
        DbKind::ClickHouse => map_clickhouse(raw, kind),
        DbKind::Oracle => {
            // `VARCHAR2(100 BYTE)` / `NUMBER(10,2)` / `TIMESTAMP(6) WITH TIME ZONE`
            let size = args.as_deref().map(|a| a.split_whitespace().next().unwrap_or(a).to_string());
            let zone = base.contains("time zone") || rest.contains("time zone");
            match base.as_str() {
                "number" | "numeric" | "decimal" | "dec" => {
                    let mut it = args.as_deref().unwrap_or("").split(',').map(|v| v.trim().parse::<i64>().ok());
                    match (it.next().flatten(), it.next().flatten()) {
                        (Some(p), None | Some(0)) if p <= 4 => "smallint".into(),
                        (Some(p), None | Some(0)) if p <= 9 => "integer".into(),
                        (Some(p), None | Some(0)) if p <= 18 => "bigint".into(),
                        (Some(p), Some(sc)) if sc > 0 && sc <= p => format!("numeric({p},{sc})"),
                        (Some(p), _) if p <= 1000 => format!("numeric({p})"),
                        _ => "numeric".into(),
                    }
                }
                "integer" | "int" | "smallint" => "numeric(38)".into(),
                "float" | "binary_double" | "double precision" => "double precision".into(),
                "binary_float" | "real" => "real".into(),
                "varchar2" | "nvarchar2" | "varchar" => with_args("varchar", &size),
                "char" | "nchar" => with_args("char", &size),
                "clob" | "nclob" | "long" => "text".into(),
                "blob" | "raw" | "long raw" | "bfile" => "bytea".into(),
                "date" => "timestamp(0)".into(),
                b if b.starts_with("timestamp") => {
                    if zone {
                        "timestamptz".into()
                    } else {
                        "timestamp".into()
                    }
                }
                b if b.starts_with("interval") => "interval".into(),
                "json" => "jsonb".into(),
                "xmltype" => "xml".into(),
                "boolean" => "boolean".into(),
                "rowid" | "urowid" | "vector" => "text".into(),
                _ => default_type_for(kind).to_string(),
            }
        }
        DbKind::Cassandra => match base.as_str() {
            "ascii" | "text" | "varchar" => "text".into(),
            "bigint" | "counter" => "bigint".into(),
            "int" => "integer".into(),
            "smallint" | "tinyint" => "smallint".into(),
            "varint" => "numeric".into(),
            "decimal" => "numeric".into(),
            "double" => "double precision".into(),
            "float" => "real".into(),
            "boolean" => "boolean".into(),
            "blob" => "bytea".into(),
            "date" => "date".into(),
            "time" => "time".into(),
            "timestamp" => "timestamptz".into(),
            "uuid" | "timeuuid" => "uuid".into(),
            "inet" => "inet".into(),
            "duration" => "interval".into(),
            _ => "jsonb".into(),
        },
        DbKind::Generic | DbKind::Redis | DbKind::MongoDb | DbKind::Elasticsearch | DbKind::Neo4j => {
            let k = DataKind::guess_from_type_name(raw);
            match k {
                DataKind::Text if base.starts_with("varchar") || base.starts_with("character varying") => with_args("varchar", &args),
                DataKind::Decimal => with_args("numeric", &args),
                DataKind::Other => default_type_for(kind).to_string(),
                k => default_type_for(k).to_string(),
            }
        }
    }
}

fn map_clickhouse(raw: &str, kind: DataKind) -> String {
    let t = raw.trim();
    let (base, args, _) = parse_type(t);
    // the argument text keeps its original case for nested types
    let inner_raw = t.find('(').and_then(|o| t.rfind(')').map(|c| t[o + 1..c].trim().to_string()));
    match base.as_str() {
        "nullable" | "lowcardinality" | "simpleaggregatefunction" => match inner_raw {
            Some(i) => {
                let inner = if base == "simpleaggregatefunction" { i.split_once(',').map(|(_, x)| x.trim().to_string()).unwrap_or(i) } else { i };
                map_clickhouse(&inner, DataKind::guess_from_type_name(&inner))
            }
            None => default_type_for(kind).to_string(),
        },
        "array" => match inner_raw {
            Some(i) => format!("{}[]", map_clickhouse(&i, DataKind::guess_from_type_name(&i))),
            None => "text[]".into(),
        },
        "int8" | "int16" | "uint8" => "smallint".into(),
        "int32" | "uint16" => "integer".into(),
        "int64" | "uint32" => "bigint".into(),
        "uint64" => "numeric(20)".into(),
        "int128" | "int256" | "uint128" | "uint256" => "numeric".into(),
        "float32" => "real".into(),
        "float64" => "double precision".into(),
        "decimal" | "decimal32" | "decimal64" | "decimal128" | "decimal256" => with_args("numeric", &args),
        "bool" | "boolean" => "boolean".into(),
        "string" | "fixedstring" | "enum8" | "enum16" | "enum" => "text".into(),
        "uuid" => "uuid".into(),
        "date" | "date32" => "date".into(),
        "datetime" => {
            if args.is_some() {
                "timestamptz".into()
            } else {
                "timestamp".into()
            }
        }
        "datetime64" => {
            let parts: Vec<String> = args.unwrap_or_default().split(',').map(|s| s.trim().to_string()).collect();
            let p = parts.first().and_then(|p| p.parse::<u32>().ok()).map(|p| p.min(6));
            let tz = parts.len() > 1;
            match (p, tz) {
                (Some(p), true) => format!("timestamptz({p})"),
                (Some(p), false) => format!("timestamp({p})"),
                (None, true) => "timestamptz".into(),
                (None, false) => "timestamp".into(),
            }
        }
        "ipv4" | "ipv6" => "inet".into(),
        "json" | "object" | "map" | "tuple" | "nested" | "variant" | "dynamic" => "jsonb".into(),
        _ => default_type_for(kind).to_string(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn collation_names() {
        assert_eq!(collation_sql("en_US.utf8"), "\"en_US.utf8\"");
        assert_eq!(collation_sql("C.UTF-8"), "\"C.UTF-8\"");
        assert_eq!(collation_sql("de_DE.ISO-8859-1"), "\"de_DE.ISO-8859-1\"");
        assert_eq!(collation_sql("myschema.mycoll"), "\"myschema\".\"mycoll\"");
        assert_eq!(collation_sql("app.ci"), "\"app\".\"ci\"");
        assert_eq!(collation_sql("\"public\".\"x\""), "\"public\".\"x\"");
        assert_eq!(collation_sql("und-x-icu"), "\"und-x-icu\"");
    }
    use std::collections::BTreeMap;

    fn sample_table() -> TableDef {
        let mut t = TableDef::new(Some("app".into()), "orders");
        let mut id = ColumnDef::new("id", "bigint").not_null();
        id.auto_increment = true;
        id.default = Some("GENERATED ALWAYS AS IDENTITY".into());
        t.columns.push(id);
        let mut code = ColumnDef::new("code", "character varying(20)").not_null();
        code.collation = Some("C".into());
        t.columns.push(code);
        let mut total = ColumnDef::new("total", "numeric(12,2)");
        total.default = Some("0".into());
        total.comment = Some("Order total, it's gross".into());
        t.columns.push(total);
        let mut taxed = ColumnDef::new("taxed", "numeric");
        taxed.generated = Some("(total * 1.1)".into());
        t.columns.push(taxed);
        t.primary_key = Some(KeyDef { name: Some("orders_pkey".into()), columns: vec!["id".into()] });
        t.unique_keys.push(KeyDef { name: Some("orders_code_key".into()), columns: vec!["code".into()] });
        t.checks.push(CheckDef { name: Some("orders_total_check".into()), expression: "(total >= (0)::numeric)".into() });
        t.foreign_keys.push(ForeignKeyDef {
            name: Some("orders_customer_fkey".into()),
            columns: vec!["code".into()],
            ref_schema: Some("app".into()),
            ref_table: "customers".into(),
            ref_columns: vec!["code".into()],
            on_delete: FkAction::Cascade,
            ..Default::default()
        });
        t.indexes.push(IndexDef { name: "orders_pkey".into(), primary: true, unique: true, columns: vec![IndexColumn::column("id")], ..Default::default() });
        t.indexes.push(IndexDef { name: "orders_code_key".into(), unique: true, columns: vec![IndexColumn::column("code")], ..Default::default() });
        t.indexes.push(IndexDef {
            name: "orders_lower_idx".into(),
            columns: vec![IndexColumn { name: "lower((code)::text)".into(), is_expression: true, descending: false }],
            definition: Some("CREATE INDEX orders_lower_idx ON app.orders USING btree (lower((code)::text)) WHERE (total > (0)::numeric)".into()),
            ..Default::default()
        });
        t.triggers.push(TriggerDef {
            name: "orders_audit".into(),
            timing: "AFTER".into(),
            events: vec!["INSERT".into()],
            for_each_row: true,
            enabled: false,
            definition: "CREATE TRIGGER orders_audit AFTER INSERT ON app.orders FOR EACH ROW EXECUTE FUNCTION app.audit()".into(),
            body: Some("app.audit()".into()),
            comment: Some("audit".into()),
        });
        t.comment = Some("Orders".into());
        t
    }

    #[test]
    fn create_table_full() {
        let ddl = PgDdl::new();
        let t = sample_table();
        let s = ddl.create_table(&t, true);
        let create = &s[0];
        assert!(create.starts_with("CREATE TABLE app.orders (\n    id bigint GENERATED ALWAYS AS IDENTITY NOT NULL,"), "{create}");
        assert!(create.contains("code character varying(20) COLLATE \"C\" NOT NULL"), "{create}");
        assert!(create.contains("total numeric(12,2) DEFAULT 0"));
        assert!(create.contains("taxed numeric GENERATED ALWAYS AS ((total * 1.1)) STORED"), "{create}");
        assert!(create.contains("CONSTRAINT orders_pkey PRIMARY KEY (id)"));
        assert!(create.contains("CONSTRAINT orders_code_key UNIQUE (code)"));
        assert!(create.contains("CONSTRAINT orders_total_check CHECK (total >= (0)::numeric)"), "{create}");
        assert!(create.contains("CONSTRAINT orders_customer_fkey FOREIGN KEY (code) REFERENCES app.customers (code) ON DELETE CASCADE"));
        assert!(s.contains(&"COMMENT ON TABLE app.orders IS 'Orders'".to_string()));
        assert!(s.contains(&"COMMENT ON COLUMN app.orders.total IS 'Order total, it''s gross'".to_string()));
        // only the secondary index, with its server definition
        let idx: Vec<&String> = s.iter().filter(|x| x.starts_with("CREATE INDEX")).collect();
        assert_eq!(idx.len(), 1);
        assert!(idx[0].contains("ON app.orders USING btree"));
        assert!(s.iter().any(|x| x == "ALTER TABLE app.orders DISABLE TRIGGER orders_audit"));
        assert!(s.iter().any(|x| x == "COMMENT ON TRIGGER orders_audit ON app.orders IS 'audit'"));
        // without FKs
        let s = ddl.create_table(&t, false);
        assert!(!s[0].contains("FOREIGN KEY"));
    }

    #[test]
    fn retarget_to_other_schema() {
        let ddl = PgDdl::new();
        let mut t = sample_table();
        t.schema = Some("copy".into());
        let s = ddl.create_table(&t, false);
        assert!(s[0].starts_with("CREATE TABLE copy.orders"));
        assert!(s.iter().any(|x| x.starts_with("CREATE INDEX orders_lower_idx ON copy.orders USING btree")));
        assert!(s.iter().any(|x| x.starts_with("CREATE TRIGGER orders_audit AFTER INSERT ON copy.orders")));
    }

    #[test]
    fn serial_and_identity_columns() {
        let mut c = ColumnDef::new("id", "integer").not_null();
        c.auto_increment = true;
        c.default = Some("nextval('app.t_id_seq'::regclass)".into());
        assert_eq!(column_definition(&c), "id serial NOT NULL");
        let mut c = ColumnDef::new("id", "bigint").not_null();
        c.auto_increment = true;
        assert_eq!(column_definition(&c), "id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL");
        let mut v = ColumnDef::new("v", "integer");
        v.generated = Some("a + 1 VIRTUAL".into());
        assert_eq!(column_definition(&v), "v integer GENERATED ALWAYS AS (a + 1) VIRTUAL");
    }

    #[test]
    fn partitioned_table() {
        let ddl = PgDdl::new();
        let mut t = TableDef::new(Some("s".into()), "events");
        t.table_kind = TableKind::PartitionedTable;
        t.columns.push(ColumnDef::new("id", "bigint").not_null());
        t.columns.push(ColumnDef::new("created", "date").not_null());
        t.partitioning = Some(PartitioningDef { strategy: "RANGE".into(), key: "created".into() });
        t.partitions.push(PartitionDef { name: "events_2024".into(), bound: "FOR VALUES FROM ('2024-01-01') TO ('2025-01-01')".into(), row_estimate: None });
        t.partitions.push(PartitionDef { name: "events_default".into(), bound: "DEFAULT".into(), row_estimate: None });
        t.options.insert("with".into(), "fillfactor=70".into());
        let s = ddl.create_table(&t, true);
        assert!(s[0].ends_with(") PARTITION BY RANGE (created) WITH (fillfactor=70)"), "{}", s[0]);
        assert_eq!(s[1], "CREATE TABLE s.events_2024 PARTITION OF s.events FOR VALUES FROM ('2024-01-01') TO ('2025-01-01')");
        assert_eq!(s[2], "CREATE TABLE s.events_default PARTITION OF s.events DEFAULT");
        // a partition on its own
        let mut p = TableDef::new(Some("s".into()), "events_2024");
        p.options.insert("partition_of".into(), "s.events".into());
        p.options.insert("partition_bound".into(), "FOR VALUES FROM ('2024-01-01') TO ('2025-01-01')".into());
        let s = ddl.create_table(&p, true);
        assert_eq!(s[0], "CREATE TABLE s.events_2024 PARTITION OF s.events FOR VALUES FROM ('2024-01-01') TO ('2025-01-01')");
    }

    #[test]
    fn alter_table_ordering() {
        let ddl = PgDdl::new();
        let from = sample_table();
        let mut to = from.clone();
        // change FK, column type, default, nullability, rename, drop a column, add one
        to.foreign_keys[0].on_delete = FkAction::Restrict;
        to.columns[2].data_type = "numeric(14,2)".into();
        to.columns[2].default = Some("1".into());
        to.columns[2].nullable = false;
        to.columns[2].comment = None;
        to.columns[1].name = "order_code".into();
        to.columns.retain(|c| c.name != "taxed");
        to.columns.push(ColumnDef::new("note", "text"));
        to.unique_keys[0].columns = vec!["order_code".into()];
        to.foreign_keys[0].columns = vec!["order_code".into()];
        to.checks.clear();
        to.comment = Some("All orders".into());
        let renamed = vec![("code".to_string(), "order_code".to_string())];
        let s = ddl.alter_table(&from, &to, &renamed);
        let pos = |needle: &str| s.iter().position(|x| x.contains(needle)).unwrap_or_else(|| panic!("{needle} not in {s:#?}"));
        assert_eq!(pos("DROP CONSTRAINT orders_customer_fkey"), 0, "{s:#?}");
        assert!(pos("DROP CONSTRAINT orders_total_check") < pos("DROP COLUMN taxed"));
        assert!(pos("DROP COLUMN taxed") < pos("RENAME COLUMN code TO order_code"));
        assert!(pos("ALTER COLUMN total DROP DEFAULT") < pos("ALTER COLUMN total TYPE numeric(14,2) USING total::numeric(14,2)"));
        assert!(pos("TYPE numeric(14,2)") < pos("ALTER COLUMN total SET DEFAULT 1"));
        assert!(s.iter().any(|x| x == "ALTER TABLE app.orders ALTER COLUMN total SET NOT NULL"));
        assert!(s.iter().any(|x| x == "COMMENT ON COLUMN app.orders.total IS NULL"));
        assert!(pos("ADD COLUMN note text") < pos("ADD CONSTRAINT orders_customer_fkey"));
        assert_eq!(pos("ADD CONSTRAINT orders_customer_fkey"), s.len() - 1, "FKs last: {s:#?}");
        assert!(s.iter().any(|x| x == "COMMENT ON TABLE app.orders IS 'All orders'"));
    }

    #[test]
    fn alter_identity() {
        let ddl = PgDdl::new();
        let mut from = TableDef::new(None, "t");
        from.columns.push(ColumnDef::new("id", "integer"));
        let mut to = from.clone();
        to.columns[0].auto_increment = true;
        to.columns[0].nullable = false;
        let s = ddl.alter_table(&from, &to, &[]);
        assert_eq!(s, vec!["ALTER TABLE t ALTER COLUMN id SET NOT NULL".to_string(), "ALTER TABLE t ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY".to_string(),]);
        let mut always = to.clone();
        always.columns[0].default = Some("GENERATED ALWAYS AS IDENTITY".into());
        let s = ddl.alter_table(&to, &always, &[]);
        assert_eq!(s, vec!["ALTER TABLE t ALTER COLUMN id SET GENERATED ALWAYS".to_string()]);
        let s = ddl.alter_table(&always, &from, &[]);
        assert!(s[0].ends_with("DROP IDENTITY IF EXISTS"), "{s:?}");
    }

    #[test]
    fn views_sequences_routines_types() {
        let ddl = PgDdl::new();
        let mut v = ViewDef { schema: Some("s".into()), name: "v".into(), definition: " SELECT 1 AS a;".into(), ..Default::default() };
        v.options = BTreeMap::from([("check_option".to_string(), "local".to_string()), ("security_barrier".to_string(), "true".to_string())]);
        let s = ddl.create_view(&v, true);
        assert_eq!(s[0], "CREATE OR REPLACE VIEW s.v WITH (security_barrier=true) AS\nSELECT 1 AS a\nWITH LOCAL CHECK OPTION");
        let mv = ViewDef { schema: Some("s".into()), name: "mv".into(), materialized: true, definition: "SELECT 1".into(), ..Default::default() };
        let s = ddl.create_view(&mv, true);
        assert_eq!(s[0], "DROP MATERIALIZED VIEW IF EXISTS s.mv");
        assert_eq!(s[1], "CREATE MATERIALIZED VIEW s.mv AS\nSELECT 1");
        assert_eq!(ddl.drop_view(&mv), "DROP MATERIALIZED VIEW s.mv");

        let seq =
            SequenceDef { schema: Some("s".into()), name: "q".into(), data_type: Some("integer".into()), increment: Some(5), start: Some(10), cycle: true, ..Default::default() };
        assert_eq!(ddl.create_sequence(&seq), "CREATE SEQUENCE s.q AS integer INCREMENT BY 5 START WITH 10 CYCLE");
        let mut seq2 = seq.clone();
        seq2.increment = Some(1);
        seq2.max_value = Some(100);
        assert_eq!(ddl.alter_sequence(&seq, &seq2), vec!["ALTER SEQUENCE s.q INCREMENT BY 1 MAXVALUE 100".to_string()]);

        let r = RoutineDef {
            schema: Some("s".into()),
            name: "f".into(),
            kind: Some(ObjectKind::Function),
            arguments: "a integer, b text".into(),
            definition: "CREATE OR REPLACE FUNCTION s.f(a integer, b text) RETURNS integer LANGUAGE sql AS $$ select 1 $$".into(),
            comment: Some("fn".into()),
            ..Default::default()
        };
        let s = ddl.create_routine(&r);
        assert_eq!(s[1], "COMMENT ON FUNCTION s.f(a integer, b text) IS 'fn'");
        assert_eq!(ddl.drop_routine(&r), "DROP FUNCTION s.f(a integer, b text)");

        let e1 = TypeDef { schema: Some("s".into()), name: "mood".into(), category: "enum".into(), elements: vec!["sad".into(), "happy".into()], ..Default::default() };
        let mut e2 = e1.clone();
        e2.elements = vec!["sad".into(), "ok".into(), "happy".into(), "great".into()];
        assert_eq!(
            ddl.alter_type(&e1, &e2),
            vec!["ALTER TYPE s.mood ADD VALUE IF NOT EXISTS 'ok' AFTER 'sad'".to_string(), "ALTER TYPE s.mood ADD VALUE IF NOT EXISTS 'great' AFTER 'happy'".to_string(),]
        );
        assert_eq!(ddl.drop_type(&e1).unwrap(), "DROP TYPE s.mood");
        let c1 = TypeDef { schema: None, name: "pt".into(), category: "composite".into(), elements: vec!["x integer".into(), "y integer".into()], ..Default::default() };
        let mut c2 = c1.clone();
        c2.elements = vec!["x bigint".into(), "z text".into()];
        assert_eq!(
            ddl.alter_type(&c1, &c2),
            vec!["ALTER TYPE pt ALTER ATTRIBUTE x TYPE bigint".to_string(), "ALTER TYPE pt DROP ATTRIBUTE y".to_string(), "ALTER TYPE pt ADD ATTRIBUTE z text".to_string(),]
        );
    }

    #[test]
    fn index_from_structure() {
        let ddl = PgDdl::new();
        let t = TableDef::new(Some("s".into()), "t");
        let idx = IndexDef {
            name: "t_gin".into(),
            method: Some("GIN".into()),
            columns: vec![IndexColumn::column("Doc")],
            include: vec![],
            predicate: Some("(deleted = false)".into()),
            ..Default::default()
        };
        assert_eq!(ddl.create_index(&t, &idx), "CREATE INDEX t_gin ON s.t USING gin (\"Doc\") WHERE (deleted = false)");
        let idx = IndexDef {
            name: "t_cov".into(),
            unique: true,
            columns: vec![IndexColumn { name: "a".into(), is_expression: false, descending: true }],
            include: vec!["b".into()],
            ..Default::default()
        };
        assert_eq!(ddl.create_index(&t, &idx), "CREATE UNIQUE INDEX t_cov ON s.t (a DESC) INCLUDE (b)");
        assert_eq!(ddl.drop_index(&t, &idx), "DROP INDEX s.t_cov");
    }

    #[test]
    fn type_mapping() {
        let m = |k: DbKind, t: &str| map_type(k, t, DataKind::guess_from_type_name(t));
        assert_eq!(m(DbKind::MySql, "tinyint(1)"), "boolean");
        assert_eq!(m(DbKind::MySql, "int unsigned"), "bigint");
        assert_eq!(m(DbKind::MySql, "int(11) unsigned"), "bigint");
        assert_eq!(m(DbKind::MySql, "bigint unsigned"), "numeric(20)");
        assert_eq!(m(DbKind::MySql, "datetime"), "timestamp");
        assert_eq!(m(DbKind::MySql, "datetime(3)"), "timestamp(3)");
        assert_eq!(m(DbKind::MySql, "longtext"), "text");
        assert_eq!(m(DbKind::MySql, "blob"), "bytea");
        assert_eq!(m(DbKind::MySql, "double"), "double precision");
        assert_eq!(m(DbKind::MySql, "enum('a','b')"), "text");
        assert_eq!(m(DbKind::MySql, "json"), "jsonb");
        assert_eq!(m(DbKind::MariaDb, "varchar(255)"), "varchar(255)");
        assert_eq!(m(DbKind::MySql, "decimal(10,2)"), "numeric(10,2)");
        assert_eq!(m(DbKind::SqlServer, "uniqueidentifier"), "uuid");
        assert_eq!(m(DbKind::SqlServer, "nvarchar(50)"), "varchar(50)");
        assert_eq!(m(DbKind::SqlServer, "nvarchar(max)"), "text");
        assert_eq!(m(DbKind::SqlServer, "bit"), "boolean");
        assert_eq!(m(DbKind::SqlServer, "datetime2"), "timestamp");
        assert_eq!(m(DbKind::SqlServer, "datetime2(7)"), "timestamp");
        assert_eq!(m(DbKind::SqlServer, "money"), "numeric(19,4)");
        assert_eq!(m(DbKind::Sqlite, "INTEGER"), "bigint");
        assert_eq!(m(DbKind::Sqlite, "VARCHAR(30)"), "varchar(30)");
        assert_eq!(m(DbKind::Sqlite, "BLOB"), "bytea");
        assert_eq!(m(DbKind::ClickHouse, "Nullable(String)"), "text");
        assert_eq!(m(DbKind::ClickHouse, "Array(Int32)"), "integer[]");
        assert_eq!(m(DbKind::ClickHouse, "LowCardinality(Nullable(String))"), "text");
        assert_eq!(m(DbKind::ClickHouse, "DateTime64(3, 'UTC')"), "timestamptz(3)");
        assert_eq!(m(DbKind::ClickHouse, "UInt64"), "numeric(20)");
        assert_eq!(m(DbKind::Oracle, "NUMBER(10,2)"), "numeric(10,2)");
        assert_eq!(m(DbKind::Oracle, "NUMBER(5)"), "integer");
        assert_eq!(m(DbKind::Oracle, "NUMBER"), "numeric");
        assert_eq!(m(DbKind::Oracle, "VARCHAR2(100 BYTE)"), "varchar(100)");
        assert_eq!(m(DbKind::Oracle, "DATE"), "timestamp(0)");
        assert_eq!(m(DbKind::Oracle, "TIMESTAMP(6) WITH TIME ZONE"), "timestamptz");
        assert_eq!(m(DbKind::Oracle, "TIMESTAMP WITH LOCAL TIME ZONE"), "timestamptz");
        assert_eq!(m(DbKind::Cassandra, "list<text>"), "jsonb");
        assert_eq!(m(DbKind::Cassandra, "timestamp"), "timestamptz");
        assert_eq!(m(DbKind::Postgres, "varchar(10)"), "varchar(10)");
        assert_eq!(default_type_for(DataKind::Json), "jsonb");
        assert_eq!(default_type_for(DataKind::DateTimeTz), "timestamptz");
    }
}
